package com.booknest.library.config;
import com.booknest.library.model.*;import com.booknest.library.repo.*;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.security.crypto.password.PasswordEncoder;
@Configuration public class SeedConfig{
 @Bean CommandLineRunner seed(UserRepository users,BookRepository books,PasswordEncoder encoder,@Value("${app.admin.email}") String admin,@Value("${app.admin.password}") String password){return args->{if(users.findByEmailIgnoreCase(admin).isEmpty()){AppUser u=new AppUser();u.name="Administrator";u.email=admin;u.password=encoder.encode(password);u.role="ADMIN";users.save(u);}if(books.count()==0){String[][] sample={{"Atomic Habits","James Clear","9780735211292","Self-help"},{"Clean Code","Robert C. Martin","9780132350884","Technology"},{"The Alchemist","Paulo Coelho","9780061122415","Fiction"},{"Introduction to Algorithms","Thomas H. Cormen","9780262046305","Technology"},{"The Psychology of Money","Morgan Housel","9780857197689","Finance"}};for(String[] s:sample){Book b=new Book();b.title=s[0];b.author=s[1];b.isbn=s[2];b.category=s[3];b.totalCopies=4;b.availableCopies=4;books.save(b);}}};}
}
